# region: digest
def digest(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    return [v for v in xs if v % 2 == 0]

# region: shape
def shape(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(shape(sift(fold(digest(raw)))))

